#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int key;
    int idx;
} Pair;

int cmp_asc_key(const void *a, const void *b) {
    const Pair *x = (const Pair *)a;
    const Pair *y = (const Pair *)b;
    if (x->key != y->key) return x->key - y->key;
    return x->idx - y->idx;
}

int cmp_desc_key(const void *a, const void *b) {
    const Pair *x = (const Pair *)a;
    const Pair *y = (const Pair *)b;
    if (x->key != y->key) return y->key - x->key;
    return x->idx - y->idx;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int *x = (int *)malloc((N + 1) * sizeof(int));
    int M = N * N;
    int *a = (int *)calloc(M + 1, sizeof(int));
    Pair *ord = (Pair *)malloc(N * sizeof(Pair));

    for (int i = 1; i <= N; i++) {
        scanf("%d", &x[i]);
        ord[i - 1].key = x[i];
        ord[i - 1].idx = i;
    }

    /* Put i at position x[i]. */
    for (int i = 1; i <= N; i++) {
        if (x[i] < 1 || x[i] > M || a[x[i]] != 0) {
            puts("No");
            free(x); free(a); free(ord);
            return 0;
        }
        a[x[i]] = i;
    }

    /* Fill left side:
       For each i, need (i-1) copies before x[i].
       Process by increasing x[i]. */
    qsort(ord, N, sizeof(Pair), cmp_asc_key);

    int p = 1;
    for (int t = 0; t < N; t++) {
        int i = ord[t].idx;
        int need = i - 1;
        while (need > 0) {
            while (p <= M && a[p] != 0) p++;
            if (p >= x[i]) {
                puts("No");
                free(x); free(a); free(ord);
                return 0;
            }
            a[p] = i;
            p++;
            need--;
        }
    }

    /* Fill right side:
       For each i, need (N-i) copies after x[i].
       Process by decreasing x[i]. */
    qsort(ord, N, sizeof(Pair), cmp_desc_key);

    p = M;
    for (int t = 0; t < N; t++) {
        int i = ord[t].idx;
        int need = N - i;
        while (need > 0) {
            while (p >= 1 && a[p] != 0) p--;
            if (p <= x[i]) {
                puts("No");
                free(x); free(a); free(ord);
                return 0;
            }
            a[p] = i;
            p--;
            need--;
        }
    }

    /* All positions must be filled now. */
    for (int i = 1; i <= M; i++) {
        if (a[i] == 0) {
            puts("No");
            free(x); free(a); free(ord);
            return 0;
        }
    }

    puts("Yes");
    for (int i = 1; i <= M; i++) {
        if (i > 1) putchar(' ');
        printf("%d", a[i]);
    }
    putchar('\n');

    free(x);
    free(a);
    free(ord);
    return 0;
}

