int main(){
    int n;
    cin >> n;
    vector<int> x(n+1);
    map<int,int> req; // position -> value required
    for(int i=1;i<=n;i++){
        cin>>x[i];
        if(req.count(x[i])){ cout<<"No\n"; return 0; }
        req[x[i]]=i;
    }

    vector<int> ans(n*n+1, 0);
    // before[i] = i-1 copies before x[i]
    // after[i] = n-i copies after x[i]
    vector<int> before_cnt(n+1), after_cnt(n+1);
    for(int i=1;i<=n;i++) before_cnt[i]=i-1, after_cnt[i]=n-i;

    // pq: (x[i], i) for before copies - most urgent first
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> pq;
    for(int i=1;i<=n;i++) if(before_cnt[i]>0) pq.push({x[i],i});
    // after pool: multiset or pq
    priority_queue<int, vector<int>, greater<>> after_pool; // values with after copies

    for(int p=1;p<=n*n;p++){
        if(req.count(p)){
            int i=req[p];
            ans[p]=i;
            if(after_cnt[i]>0) for(int k=0;k<after_cnt[i];k++) after_pool.push(i); // add after copies
        } else {
            // pick from pq if top has x[i]>p, else from after_pool
            if(!pq.empty() && pq.top().first > p){
                auto [xi,i]=pq.top(); pq.pop();
                ans[p]=i; before_cnt[i]--;
                if(before_cnt[i]>0) pq.push({xi,i});
            } else if(!after_pool.empty()){
                ans[p]=after_pool.top(); after_pool.pop();
            } else { cout<<"No\n"; return 0; }
        }
    }
    // verify
    cout<<"Yes\n";
    for(int p=1;p<=n*n;p++) cout<<ans[p]<<" \n"[p==n*n];
}

