int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int> x(N + 1);
    for (int i = 1; i <= N; ++i) cin >> x[i];

    // Pair: (position of i-th occurrence, value i)
    vector<pair<int,int>> v;
    for (int i = 1; i <= N; ++i) v.push_back({x[i], i});
    sort(v.begin(), v.end());

    // Basic necessary condition: all x_i must be distinct and in [1, N^2]
    for (int i = 0; i < N; ++i) {
        if (v[i].first < 1 || v[i].first > N * N) {
            cout << "No\n";
            return 0;
        }
        if (i && v[i].first == v[i-1].first) {
            cout << "No\n";
            return 0;
        }
    }

    int M = N * N;
    vector<int> ans(M + 1, 0);

    // Place each i at position x_i first.
    for (int i = 1; i <= N; ++i) ans[x[i]] = i;

    // Fill left-to-right before each special position:
    // for number i, we need exactly (i-1) copies before x_i.
    priority_queue<int, vector<int>, greater<int>> pq;
    for (int i = 1; i <= N; ++i) pq.push(i);

    int ptr = 1;
    for (auto [pos, val] : v) {
        int need = val - 1; // copies needed before x_val
        while (need > 0) {
            while (ptr <= M && ans[ptr] != 0) ++ptr;
            if (ptr >= pos || ptr > M || pq.empty()) {
                cout << "No\n";
                return 0;
            }
            int t = pq.top(); pq.pop();
            ans[ptr] = t;
            --need;
        }
        // After placing (val-1) copies before x_val, remove val from pq
        // because its special occurrence at x_val is now considered placed.
        if (pq.empty() || pq.top() != val) {
            // val should be the smallest not-yet-fixed number here
            // otherwise impossible
            priority_queue<int, vector<int>, greater<int>> tmp = pq;
            bool found = false;
            while (!tmp.empty()) {
                if (tmp.top() == val) found = true;
                tmp.pop();
            }
            if (!found) {
                cout << "No\n";
                return 0;
            }
            // remove val from pq
            vector<int> buf;
            while (!pq.empty() && pq.top() != val) {
                buf.push_back(pq.top());
                pq.pop();
            }
            if (pq.empty()) {
                cout << "No\n";
                return 0;
            }
            pq.pop();
            for (int z : buf) pq.push(z);
        } else {
            pq.pop();
        }
    }

    // Now fill remaining cells from right to left.
    // For each i, after x_i we need N-i more copies.
    priority_queue<int> pq2;
    for (int i = 1; i <= N; ++i) {
        for (int k = 0; k < N - i; ++k) pq2.push(i);
    }

    ptr = M;
    for (int idx = N - 1; idx >= 0; --idx) {
        int pos = v[idx].first;
        while (ptr > pos) {
            if (ans[ptr] == 0) {
                if (pq2.empty()) {
                    cout << "No\n";
                    return 0;
                }
                ans[ptr] = pq2.top();
                pq2.pop();
            }
            --ptr;
        }
        --ptr; // skip the fixed position itself
    }

    // Fill any remaining empty cells (should not happen if logic is correct)
    while (ptr >= 1) {
        if (ans[ptr] == 0) {
            if (pq2.empty()) {
                cout << "No\n";
                return 0;
            }
            ans[ptr] = pq2.top();
            pq2.pop();
        }
        --ptr;
    }

    if (!pq2.empty()) {
        cout << "No\n";
        return 0;
    }

    // Final verification
    vector<int> cnt(N + 1, 0);
    for (int i = 1; i <= M; ++i) {
        if (ans[i] < 1 || ans[i] > N) {
            cout << "No\n";
            return 0;
        }
        cnt[ans[i]]++;
        if (cnt[ans[i]] == ans[i] && i != x[ans[i]]) {
            cout << "No\n";
            return 0;
        }
    }
    for (int i = 1; i <= N; ++i) {
        if (cnt[i] != N) {
            cout << "No\n";
            return 0;
        }
    }

    cout << "Yes\n";
    for (int i = 1; i <= M; ++i) {
        if (i > 1) cout << ' ';
        cout << ans[i];
    }
    cout << '\n';
    return 0;
}

