public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int[] x = new int[N + 1];
        for (int i = 1; i <= N; i++) x[i] = fs.nextInt();

        int M = N * N;
        int[] ans = new int[M + 1];
        boolean[] usedPos = new boolean[M + 1];

        for (int i = 1; i <= N; i++) {
            if (x[i] < 1 || x[i] > M || usedPos[x[i]]) {
                System.out.println("No");
                return;
            }
            usedPos[x[i]] = true;
            ans[x[i]] = i;
        }

        // Fill left side:
        // For each i, we need exactly (i-1) copies of i before position x[i].
        // Greedily process by increasing x[i].
        Integer[] orderLeft = new Integer[N];
        for (int i = 0; i < N; i++) orderLeft[i] = i + 1;
        Arrays.sort(orderLeft, Comparator.comparingInt(o -> x[o]));

        PriorityQueue<Integer> needLeft = new PriorityQueue<>();
        int ptr = 0;
        for (int pos = 1; pos <= M; pos++) {
            while (ptr < N && x[orderLeft[ptr]] == pos) {
                int v = orderLeft[ptr];
                for (int k = 0; k < v - 1; k++) needLeft.add(v);
                ptr++;
            }
            if (ans[pos] == 0) {
                if (needLeft.isEmpty()) {
                    System.out.println("No");
                    return;
                }
                ans[pos] = needLeft.poll();
            }
        }
        if (!needLeft.isEmpty()) {
            System.out.println("No");
            return;
        }

        // Clear anchor positions, keep only fixed x[i] positions,
        // then fill right side independently.
        Arrays.fill(ans, 0);
        for (int i = 1; i <= N; i++) ans[x[i]] = i;

        // Fill right side:
        // For each i, we need exactly (N-i) copies of i after position x[i].
        // Greedily process by decreasing x[i].
        Integer[] orderRight = new Integer[N];
        for (int i = 0; i < N; i++) orderRight[i] = i + 1;
        Arrays.sort(orderRight, (a, b) -> Integer.compare(x[b], x[a]));

        PriorityQueue<Integer> needRight = new PriorityQueue<>(Collections.reverseOrder());
        ptr = 0;
        for (int pos = M; pos >= 1; pos--) {
            while (ptr < N && x[orderRight[ptr]] == pos) {
                int v = orderRight[ptr];
                for (int k = 0; k < N - v; k++) needRight.add(v);
                ptr++;
            }
            if (ans[pos] == 0) {
                if (needRight.isEmpty()) {
                    System.out.println("No");
                    return;
                }
                ans[pos] = needRight.poll();
            }
        }
        if (!needRight.isEmpty()) {
            System.out.println("No");
            return;
        }

        // Verify
        int[] cnt = new int[N + 1];
        for (int pos = 1; pos <= M; pos++) {
            int v = ans[pos];
            if (v < 1 || v > N) {
                System.out.println("No");
                return;
            }
            cnt[v]++;
            if (cnt[v] == v && pos != x[v]) {
                System.out.println("No");
                return;
            }
        }
        for (int i = 1; i <= N; i++) {
            if (cnt[i] != N) {
                System.out.println("No");
                return;
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.append("Yes\n");
        for (int i = 1; i <= M; i++) {
            if (i > 1) sb.append(' ');
            sb.append(ans[i]);
        }
        sb.append('\n');
        System.out.print(sb.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
